export function catalogFiltersFor(categorySlug:string,subcategory?:string){const sets=categoryFilterSets.filter(item=>item.categorySlug===categorySlug&&(!subcategory||item.subcategory===subcategory));const merged=new Map<string,CatalogFilter>();for(const set of sets)for(const filter of set.filters){const previous=merged.get(filter.key);if(!previous)merged.set(filter.key,{...filter,values:[...filter.values]});else for(const value of filter.values)if(!previous.values.includes(value))previous.values.push(value)}return [...merged.values()]}
